#!/bin/bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"; APP="$ROOT/dist/The 6K Extension Installer.app"; mkdir -p "$ROOT/dist/build" "$APP/Contents/MacOS" "$APP/Contents/Resources/payload/extensions"; rm -f "$APP/Contents/Resources/yomitan-api-host"; swiftc "$ROOT/macos/Sources/main.swift" -o "$ROOT/dist/build/installer" -framework Cocoa -framework Network; cp "$ROOT/dist/build/installer" "$APP/Contents/MacOS/The 6K Extension Installer"; cp "$ROOT/macos/Info.plist" "$APP/Contents/Info.plist"; cp -R "$ROOT/payload/extensions/the-6k-extension" "$APP/Contents/Resources/payload/extensions/"; cp "$ROOT/helper/yomitan_api.py" "$ROOT/helper/LICENSE.yomitan-api.txt" "$APP/Contents/Resources/"; codesign --force --deep --sign - "$APP"; (cd "$ROOT/dist" && ditto -c -k --sequesterRsrc --keepParent "The 6K Extension Installer.app" The-6K-Extension-Installer-mac.zip); shasum -a 256 "$ROOT/dist/The-6K-Extension-Installer-mac.zip" > "$ROOT/dist/SHA256SUMS.txt"
